<?php declare(strict_types=1); $title='Korábbi foglalások importálása – A Bata'; require __DIR__.'/_layout_start.php'; $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<section class="admin-page"><p class="eyebrow">Foglalások</p><h1>Korábbi foglalások importálása</h1>
<?php if (!empty($error)): ?><p class="alert"><?= $e($error) ?></p><?php endif; ?>
<?php if ($preview===null): ?><p>WP Booking System CSV export feltöltése. Alapértelmezésben csak az „A Bata - naptár” és az elfogadott vagy függő foglalások kerülnek kiválasztásra. A tesztnaptár és a törölt sorok kimaradnak.</p><form method="post" enctype="multipart/form-data" action="/admin/bookings/import/preview"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label>CSV fájl <input type="file" name="csv" accept=".csv,text/csv" required></label><button type="submit">Előnézet készítése</button></form>
<?php else: ?><h2>Importálási előnézet</h2><dl class="facts"><div><dt>Összes sor</dt><dd><?= $preview->total() ?></dd></div><div><dt>Érvényes sor</dt><dd><?= $preview->valid() ?></dd></div><div><dt>Alapértelmezés szerint kiválasztva</dt><dd><?= $preview->selected(new \App\Application\LegacyImport\LegacyImportOptions()) ?></dd></div><div><dt>Hibás sor</dt><dd><?= $preview->invalid() ?></dd></div><div><dt>Már importált sor</dt><dd><?= (int)($duplicates ?? 0) ?></dd></div><div><dt>Ütközésgyanús megerősített sor</dt><dd><?= (int)($conflicts ?? 0) ?></dd></div></dl><h3>Státusz mapping</h3><ul><?php foreach($preview->mappedStatuses() as $status=>$count): ?><li><?= $e($status) ?>: <?= $count ?></li><?php endforeach; ?></ul><p>Figyelmeztetések: <?= $preview->warningCount() ?>; hibák: <?= $preview->errorCount() ?></p><h3>Forrás státuszok</h3><ul><?php foreach($preview->sourceStatuses as $status=>$count): ?><li><?= $e($status) ?>: <?= $count ?></li><?php endforeach; ?></ul><h3>Naptárak</h3><ul><?php foreach($preview->calendars as $calendar=>$count): ?><li><?= $e($calendar) ?>: <?= $count ?></li><?php endforeach; ?></ul><?php if ($preview->errorCount() || $preview->warningCount()): ?><h3>Figyelmeztetések és hibák</h3><ul><?php foreach($preview->rows as $row): ?><?php if ($row->errors || $row->warnings): ?><li><?= $e($row->sourceBookingId) ?>: <?= $e(implode(', ', array_merge($row->errors, $row->warnings))) ?></li><?php endif; ?><?php endforeach; ?></ul><?php endif; ?><p class="alert">A megerősítettként importált jövőbeli foglalások foglalttá teszik az időszakot. A régi export áradatot és jogi verziót nem tartalmaz, ezeket nem pótoljuk.</p><form method="post" action="/admin/bookings/import/commit"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label class="checkbox-label"><input type="checkbox" name="include_trash" value="1"> <span>Törölt sorok bevonása (ezek érvénytelenítettként kerülnek be)</span></label><button type="submit">Foglalások importálása</button></form><?php endif; ?></section><?php require __DIR__.'/_layout_end.php'; ?>
